{* Code generated by xgen. DO NOT EDIT.
    Source: xgen/specs/organisms/nav-actions.json
    The buttons at the end of a top bar: login, the call to action and the theme button (it only reports the press). No wrapper: they sit in the row of the bar.
    Props (p): login, loginHref, cta, ctaHref, actions, tone, themeLabel. *}
{var $v_login = ($p['login'] ?? null)}
{var $v_loginHref = ($p['loginHref'] ?? '#/login')}
{var $v_cta = ($p['cta'] ?? null)}
{var $v_ctaHref = ($p['ctaHref'] ?? null)}
{var $v_actions = ($p['actions'] ?? 'cta')}
{var $v_tone = ($p['tone'] ?? 'default')}
{var $v_themeLabel = ($p['themeLabel'] ?? null)}
{if ui_t($v_login)}
  {capture $c_1}
    {=ui_text($v_login)}
  {/capture}
  {=ui_include('ui/button/button.latte', ['p' => ['Variant' => 'ghost', 'Size' => 'sm', 'Href' => ui_s($v_loginHref), 'Class' => ui_s((ui_t(ui_eq($v_tone, 'inverse')) ? 'text-background hover:bg-background/10' : '')), 'Attrs' => ui_attrs(['data-testid', 'nav-login'])], 'children' => $c_1])|noescape}
{/if}
{if ui_t(ui_and([ui_eq($v_actions, 'cta'), $v_cta]))}
  {capture $c_2}
    {=ui_text($v_cta)}
  {/capture}
  {=ui_include('ui/button/button.latte', ['p' => ['Variant' => ui_s((ui_t(ui_eq($v_tone, 'inverse')) ? 'secondary' : 'default')), 'Size' => 'sm', 'Href' => ui_s($v_ctaHref), 'Attrs' => ui_attrs(['data-testid', 'header-cta'])], 'children' => $c_2])|noescape}
{/if}
{if ui_t($v_themeLabel)}
  {capture $c_3}
    {=ui_text($v_themeLabel)}
  {/capture}
  {=ui_include('ui/button/button.latte', ['p' => ['Variant' => 'outline', 'Size' => 'sm', 'Attrs' => ui_attrs(['data-testid', 'theme-toggle'])], 'children' => $c_3])|noescape}
{/if}
